814: /// Helper function to aggregate a byte buffer representing a `.txt` or `.DAT` log.
815: pub fn aggregate_buffer(
816:     buffer: &[u8],
817:     egm: Option<Egm2008Model>,
818: ) -> Result<FlightDataset, ExportError> {
819:     if buffer.is_empty() {
820:         return Ok(FlightDataset::new());
821:     }
822: 
823:     // Check for DAT magic 0x55
824:     if buffer[0] == flightreader_core::dat::DAT_MAGIC {
825:         let mut aggregator = TelemetryAggregator::new(egm);
826:         aggregator.metadata.log_type = "DJI_DAT".to_string();
827:         let iter = flightreader_core::dat::DatFrameIterator::new(buffer);
828:         for frame in iter.flatten() {
829:             let _ = aggregator.process_dat_frame(&frame);
830:         }
831: 
832:         Ok(aggregator.finish())
833:     } else {
834:         // Parse as DJI .txt
835:         let header = flightreader_core::txt::TxtHeader::parse(buffer)?;
836:         let mut aggregator = TelemetryAggregator::new(egm).with_version(header.version);
837:         aggregator.metadata.log_type = format!("DJI_TXT_V{}", header.version);
838: 
839:         // Extract details block start timestamp if present
840:         if header.details_offset >= 0 {
841:             let offset = header.details_offset as usize;
842:             if offset + 99 <= buffer.len() {
843:                 let ts = LittleEndian::read_i64(&buffer[offset + 91..offset + 99]);
844:                 if ts > 0 && ts < 2_500_000_000_000 {
845:                     aggregator.set_details_start_ms(ts);
846:                 }
847:             }
848:         }
849: 
850:         let iter = flightreader_core::txt::RecordEnvelopeIterator::new(buffer, &header)?;
851:         for env in iter.flatten() {
852:             let _ = aggregator.process_envelope(&env);
853:         }
854:         Ok(aggregator.finish())
855:     }
856: }
