332: /// Downsamples telemetry points to target frequency while strictly preserving critical landmark events.
333: fn decimate_with_landmarks(points: &[TelemetryPoint], rate_hz: f64) -> Vec<TelemetryPoint> {
334:     if points.len() <= 2 {
335:         return points.to_vec();
336:     }
337: 
338:     let bin_duration_s = 1.0 / rate_hz;
339: 
340:     // --- 1. Identify all critical landmark indices ---
341:     let mut pinned = HashSet::new();
342: 
343:     // Start and End boundaries
344:     pinned.insert(0);
345:     pinned.insert(points.len() - 1);
346: 
347:     // Takeoff point (first motor-up instant)
348:     if let Some(takeoff_idx) = points.iter().position(|p| p.is_motor_on) {
349:         pinned.insert(takeoff_idx);
350:     }
351: 
352:     // Landing point (first motor-down instant after flight)
353:     if let Some(last_motor_idx) = points.iter().rposition(|p| p.is_motor_on) {
354:         if last_motor_idx + 1 < points.len() {
355:             pinned.insert(last_motor_idx + 1);
356:         } else {
357:             pinned.insert(last_motor_idx);
358:         }
359:     }
360: 
361:     // Flight mode transitions
362:     for i in 1..points.len() {
363:         if points[i].flight_mode != points[i - 1].flight_mode {
364:             pinned.insert(i);
365:         }
366:     }
367: 
368:     // RTH failsafe activations
369:     for i in 1..points.len() {
370:         if points[i].is_failsafe_active && !points[i - 1].is_failsafe_active {
371:             pinned.insert(i);
372:         }
373:     }
374: 
375:     // Operational warnings & tips
376:     for (i, p) in points.iter().enumerate() {
377:         if p.app_warning.is_some() || p.app_tip.is_some() {
378:             pinned.insert(i);
379:         }
380:     }
381: 
382:     // Extrema (Maximum Altitude and Maximum Speed)
383:     let mut max_alt_idx = 0;
384:     let mut max_spd_idx = 0;
385:     let mut max_alt = f64::NEG_INFINITY;
386:     let mut max_spd = f64::NEG_INFINITY;
387: 
388:     for (i, p) in points.iter().enumerate() {
389:         if p.altitude_msl > max_alt {
390:             max_alt = p.altitude_msl;
391:             max_alt_idx = i;
392:         }
393:         if p.ground_speed_mps > max_spd {
394:             max_spd = p.ground_speed_mps;
395:             max_spd_idx = i;
396:         }
397:     }
398:     pinned.insert(max_alt_idx);
399:     pinned.insert(max_spd_idx);
400: 
401:     // --- 2. Partition into uniform time bins ---
402:     let base_elapsed = points[0].elapsed_s;
403:     let last_elapsed = points.last().unwrap().elapsed_s;
404:     let total_duration = (last_elapsed - base_elapsed).max(0.0);
405:     let num_bins = ((total_duration / bin_duration_s).ceil() as usize).max(1);
406: 
407:     // Group point indices by bin
408:     let mut bins: Vec<Vec<usize>> = vec![Vec::new(); num_bins];
409:     for (i, p) in points.iter().enumerate() {
410:         let rel_t = p.elapsed_s - base_elapsed;
411:         let bin_idx = ((rel_t / bin_duration_s).floor() as usize).min(num_bins - 1);
412:         bins[bin_idx].push(i);
413:     }
414: 
415:     // --- 3. Bin Selection Logic ---
416:     let mut selected_indices = HashSet::new();
417: 
418:     // Always include all pinned landmarks
419:     for &idx in &pinned {
420:         selected_indices.insert(idx);
421:     }
422: 
423:     for (b_idx, bin_points) in bins.iter().enumerate() {
424:         if bin_points.is_empty() {
425:             continue;
426:         }
427: 
428:         // Check if any pinned point is already in this bin
429:         let has_pinned = bin_points.iter().any(|idx| pinned.contains(idx));
430:         if !has_pinned {
431:             // Pick point closest to bin center
432:             let bin_center_t = base_elapsed + (b_idx as f64 + 0.5) * bin_duration_s;
433:             let mut best_idx = bin_points[0];
434:             let mut best_diff = (points[best_idx].elapsed_s - bin_center_t).abs();
435: 
436:             for &idx in &bin_points[1..] {
437:                 let diff = (points[idx].elapsed_s - bin_center_t).abs();
438:                 if diff < best_diff {
439:                     best_diff = diff;
440:                     best_idx = idx;
441:                 }
442:             }
443:             selected_indices.insert(best_idx);
444:         }
445:     }
446: 
447:     // --- 4. Sort indices and gather output ---
448:     let mut sorted_indices: Vec<usize> = selected_indices.into_iter().collect();
449:     sorted_indices.sort_unstable();
450: 
451:     sorted_indices
452:         .into_iter()
453:         .map(|idx| points[idx].clone())
454:         .collect()
455: }
